  2402  static exr_result_t
  2403  update_chunk_offsets (
  2404      struct _internal_exr_context*     ctxt,
  2405      struct _internal_exr_seq_scratch* scratch)
  2406  {
  2407      struct _internal_exr_part *curpart, *prevpart;
  2408
  2409      exr_result_t rv = EXR_ERR_SUCCESS;
  2410
  2411      if (!ctxt->parts) return EXR_ERR_INVALID_ARGUMENT;
  2412
  2413      ctxt->parts[0]->chunk_table_offset =
  2414          scratch->fileoff - (uint64_t) scratch->navail;
  2415      prevpart = ctxt->parts[0];
  2416
  2417      for (int p = 0; p < ctxt->num_parts; ++p)
  2418      {
  2419          curpart = ctxt->parts[p];
  2420
  2421          rv = internal_exr_compute_tile_information (ctxt, curpart, 0);
  2422          if (rv != EXR_ERR_SUCCESS) break;
  2423
  2424          int32_t ccount = internal_exr_compute_chunk_offset_size (curpart);
  2425          if (ccount < 0)
  2426          {
  2427              rv = ctxt->print_error (
  2428                  ctxt,
  2429                  EXR_ERR_INVALID_ATTR,
  2430                  "Invalid chunk count (%d) for part '%s'",
  2431                  ccount,
  2432                  (curpart->name ? curpart->name->string->str : "<first>"));
  2433              break;
  2434          }
  2435
  2436          if (curpart->chunk_count < 0)
  2437              curpart->chunk_count = ccount;
  2438          else if (curpart->chunk_count != ccount)
  2439          {
  2440              /* fatal error or just ignore it? c++ seemed to just ignore it entirely, we can at least warn */
  2441              /* rv = */
  2442              ctxt->print_error (
  2443                  ctxt,
  2444                  EXR_ERR_INVALID_ATTR,
  2445                  "Invalid chunk count (%d) for part '%s', expect (%d)",
  2446                  curpart->chunk_count,
  2447                  (curpart->name ? curpart->name->string->str : "<first>"),
  2448                  ccount);
  2449              curpart->chunk_count = ccount;
  2450          }
  2451          if (prevpart != curpart)
  2452              curpart->chunk_table_offset =
  2453                  prevpart->chunk_table_offset +
  2454                  sizeof (uint64_t) * (size_t) (prevpart->chunk_count);
  2455          prevpart = curpart;
  2456      }
  2457      return rv;
  2458  }
