  2462  static exr_result_t
  2463  read_magic_and_flags (
  2464      struct _internal_exr_context* ctxt, uint32_t* outflags, uint64_t* initpos)
  2465  {
  2465  {
  2466      uint32_t     magic_and_version[2];
  2467      uint32_t     flags;
  2468      exr_result_t rv      = EXR_ERR_UNKNOWN;
  2469      uint64_t     fileoff = 0;
  2470      int64_t      nread   = 0;
  2471
  2472      rv = ctxt->do_read (
  2473          ctxt,
  2474          magic_and_version,
  2475          sizeof (uint32_t) * 2,
  2476          &fileoff,
  2477          &nread,
  2478          EXR_MUST_READ_ALL);
  2479      if (rv != EXR_ERR_SUCCESS)
  2480      {
  2481          ctxt->report_error (
  2482              ctxt, EXR_ERR_READ_IO, "Unable to read magic and version flags");
  2483          return rv;
  2484      }
  2485
  2486      *initpos = sizeof (uint32_t) * 2;
  2487
  2488      priv_to_native32 (magic_and_version, 2);
  2489      if (magic_and_version[0] != 20000630)
  2490      {
  2491          rv = ctxt->print_error (
  2492              ctxt,
  2493              EXR_ERR_FILE_BAD_HEADER,
  2494              "File is not an OpenEXR file: magic 0x%08X (%d) flags 0x%08X",
  2495              magic_and_version[0],
  2496              (int) magic_and_version[0],
  2497              magic_and_version[1]);
  2498          return rv;
  2499      }
  2500
  2501      flags = magic_and_version[1];
  2502
  2503      ctxt->version = flags & EXR_FILE_VERSION_MASK;
  2504      if (ctxt->version != 2)
  2505      {
  2506          rv = ctxt->print_error (
  2507              ctxt,
  2508              EXR_ERR_FILE_BAD_HEADER,
  2509              "File is of an unsupported version: %d, magic 0x%08X flags 0x%08X",
  2510              (int) ctxt->version,
  2511              magic_and_version[0],
  2512              magic_and_version[1]);
  2513          return rv;
  2514      }
  2515
  2516      flags = flags & ~((uint32_t) EXR_FILE_VERSION_MASK);
  2517      if ((flags & ~((uint32_t) EXR_VALID_FLAGS)) != 0)
  2518      {
  2519          rv = ctxt->print_error (
  2520              ctxt,
  2521              EXR_ERR_FILE_BAD_HEADER,
  2522              "File has an unsupported flags: magic 0x%08X flags 0x%08X",
  2523              magic_and_version[0],
  2524              magic_and_version[1]);
  2525          return rv;
  2526      }
  2527      *outflags = flags;
  2528      return EXR_ERR_SUCCESS;
  2529  }
