    35  static inline int
    36  shiftAndRound (int x, int shift)
    37  {
    38      //
    39      // Compute
    40      //
    41      //     y = x * pow (2, -shift),
    42      //
    43      // then round y to the nearest integer.
    44      // In case of a tie, where y is exactly
    45      // halfway between two integers, round
    46      // to the even one.
    47      //
    48
    49      x <<= 1;
    50      int a = (1 << shift) - 1;
    51      shift += 1;
    52      int b = (x >> shift) & 1;
    53      return (x + a + b) >> shift;
    54  }
    55
    56  /*
    57   * Pack a block of 4 by 4 16-bit pixels (32 bytes) into
    58   * either 14 or 3 bytes.
    59   *
    60   *
    61   * Integers s[0] ... s[15] represent floating-point numbers
    62   * in what is essentially a sign-magnitude format.  Convert
    63   * s[0] .. s[15] into a new set of integers, t[0] ... t[15],
    64   * such that if t[i] is greater than t[j], the floating-point
    65   * number that corresponds to s[i] is always greater than
    66   * the floating-point number that corresponds to s[j].
    67   *
    68   * Also, replace any bit patterns that represent NaNs or
    69   * infinities with bit patterns that represent floating-point
    70   * zeroes.
    71   *
    72   *      bit pattern     floating-point          bit pattern
    73   *      in s[i]         value                   in t[i]
    74   *
    75   *  0x7fff              NAN                     0x8000
    76   *  0x7ffe              NAN                     0x8000
    77   *        ...                                     ...
    78   *  0x7c01              NAN                     0x8000
    79   *  0x7c00              +infinity               0x8000
    80   *  0x7bff              +HALF_MAX               0xfbff
    81   *  0x7bfe                                      0xfbfe
    82   *  0x7bfd                                      0xfbfd
    83   *        ...                                     ...
    84   *  0x0002              +2 * HALF_MIN           0x8002
    85   *  0x0001              +HALF_MIN               0x8001
    86   *  0x0000              +0.0                    0x8000
    87   *  0x8000              -0.0                    0x7fff
    88   *  0x8001              -HALF_MIN               0x7ffe
    89   *  0x8002              -2 * HALF_MIN           0x7ffd
    90   *        ...                                     ...
    91   *  0xfbfd                                      0x0f02
    92   *  0xfbfe                                      0x0401
    93   *  0xfbff              -HALF_MAX               0x0400
    94   *  0xfc00              -infinity               0x8000
    95   *  0xfc01              NAN                     0x8000
    96   *        ...                                     ...
    97   *  0xfffe              NAN                     0x8000
    98   *  0xffff              NAN                     0x8000
    99   */
   100  static int
   101  pack (const uint16_t s[16], uint8_t b[14], int flatfields, int exactmax)
   102  {
   103      int      d[16];
   104      int      r[15];
   105      int      rMin;
   106      int      rMax;
   107      uint16_t t[16];
   108      uint16_t tMax;
   109      int      shift = -1;
   110
   111      for (int i = 0; i < 16; ++i)
   112      {
   113          if ((s[i] & 0x7c00) == 0x7c00)
   114              t[i] = 0x8000;
   115          else if (s[i] & 0x8000)
   116              t[i] = ~s[i];
   117          else
   118              t[i] = s[i] | 0x8000;
   119      }
   120
   121      // find max
   122      tMax = 0;
   123      for (int i = 0; i < 16; ++i)
   124          if (tMax < t[i]) tMax = t[i];
   125
   126      //
   127      // Compute a set of running differences, r[0] ... r[14]:
   128      // Find a shift value such that after rounding off the
   129      // rightmost bits and shifting all differences are between
   130      // -32 and +31.  Then bias the differences so that they
   131      // end up between 0 and 63.
   132      //
   133
   134      const int bias = 0x20;
   135
   136      do
   137      {
   138          shift += 1;
   139
   140          //
   141          // Compute absolute differences, d[0] ... d[15],
   142          // between tMax and t[0] ... t[15].
   143          //
   144          // Shift and round the absolute differences.
   145          //
   146
   147          for (int i = 0; i < 16; ++i)
   148              d[i] = shiftAndRound (tMax - t[i], shift);
   149
   150          //
   151          // Convert d[0] .. d[15] into running differences
   152          //
   153
   154          r[0] = d[0] - d[4] + bias;
   155          r[1] = d[4] - d[8] + bias;
   156          r[2] = d[8] - d[12] + bias;
   157
   158          r[3] = d[0] - d[1] + bias;
   159          r[4] = d[4] - d[5] + bias;
   160          r[5] = d[8] - d[9] + bias;
   161          r[6] = d[12] - d[13] + bias;
   162
   163          r[7]  = d[1] - d[2] + bias;
   164          r[8]  = d[5] - d[6] + bias;
   165          r[9]  = d[9] - d[10] + bias;
   166          r[10] = d[13] - d[14] + bias;
   167
   168          r[11] = d[2] - d[3] + bias;
   169          r[12] = d[6] - d[7] + bias;
   170          r[13] = d[10] - d[11] + bias;
   171          r[14] = d[14] - d[15] + bias;
   172
   173          rMin = r[0];
   174          rMax = r[0];
   175
   176          for (int i = 1; i < 15; ++i)
   177          {
   178              if (rMin > r[i]) rMin = r[i];
   179
   180              if (rMax < r[i]) rMax = r[i];
   181          }
   182      } while (rMin < 0 || rMax > 0x3f);
   183
   184      if (rMin == bias && rMax == bias && flatfields)
