   253  /**************************************/
   254
   255  static exr_result_t
   256  undo_pxr24_impl (
   257      exr_decode_pipeline_t* decode,
   258      const void*            compressed_data,
   259      uint64_t               comp_buf_size,
   260      void*                  uncompressed_data,
   261      uint64_t               uncompressed_size,
   262      void*                  scratch_data,
   263      uint64_t               scratch_size)
   264  {
   265      uLong          outSize = (uLong) uncompressed_size;
   266      int            rstat;
   267      uint8_t*       out    = uncompressed_data;
   268      uint64_t       nOut   = 0;
   269      uint64_t       nDec   = 0;
   270      const uint8_t* lastIn = scratch_data;
   271
   272      if (scratch_size < uncompressed_size) return EXR_ERR_INVALID_ARGUMENT;
   273
   274      rstat = uncompress (
   275          (Bytef*) scratch_data,
   276          &outSize,
   277          (const Bytef*) compressed_data,
   278          (uLong) comp_buf_size);
   279
   280      if (rstat != Z_OK) return EXR_ERR_CORRUPT_CHUNK;
   281
   282      for (int y = 0; y < decode->chunk.height; ++y)
   283      {
   284          int cury = y + decode->chunk.start_y;
   285
   286          for (int c = 0; c < decode->channel_count; ++c)
   287          {
   288              const exr_coding_channel_info_t* curc = decode->channels + c;
   289              int                              w    = curc->width;
   290              uint64_t                         nBytes =
   291                  (uint64_t) (w) * (uint64_t) (curc->bytes_per_element);
   292
   293              if (curc->height == 0 ||
   294                  (curc->y_samples > 1 && (cury % curc->y_samples) != 0))
   295                  continue;
   296
   297              if (nOut + nBytes > uncompressed_size) return EXR_ERR_OUT_OF_MEMORY;
   298
   299              switch (curc->data_type)
   300              {
   301                  case EXR_PIXEL_UINT: {
   302                      const uint8_t* ptr[4];
   303                      uint32_t       pixel = 0;
   304                      uint32_t*      dout  = (uint32_t*) (out);
   305
   306                      ptr[0] = lastIn;
   307                      lastIn += w;
   308                      ptr[1] = lastIn;
   309                      lastIn += w;
   310                      ptr[2] = lastIn;
   311                      lastIn += w;
   312                      ptr[3] = lastIn;
   313                      lastIn += w;
   314
   315                      if (nDec + nBytes > outSize) return EXR_ERR_CORRUPT_CHUNK;
   316
   317                      for (int x = 0; x < w; ++x)
   318                      {
   319                          uint32_t diff =
   320                              (((uint32_t) (*(ptr[0]++)) << 24) |
   321                               ((uint32_t) (*(ptr[1]++)) << 16) |
   322                               ((uint32_t) (*(ptr[2]++)) << 8) |
   323                               ((uint32_t) (*(ptr[3]++))));
   324                          pixel += diff;
   325                          unaligned_store32 (dout, pixel);
   326                          ++dout;
   327                      }
   328                      nDec += nBytes;
   329                      break;
   330                  }
   331                  case EXR_PIXEL_HALF: {
   332                      const uint8_t* ptr[2];
   333                      uint32_t       pixel = 0;
   334                      uint16_t*      dout  = (uint16_t*) (out);
   335
   336                      ptr[0] = lastIn;
   337                      lastIn += w;
   338                      ptr[1] = lastIn;
   339                      lastIn += w;
   340
   341                      if (nDec + nBytes > outSize) return EXR_ERR_CORRUPT_CHUNK;
   342
   343                      for (int x = 0; x < w; ++x)
   344                      {
   345                          uint32_t diff =
   346                              (((uint32_t) (*(ptr[0]++)) << 8) |
   347                               ((uint32_t) (*(ptr[1]++))));
   348                          pixel += diff;
   349                          unaligned_store16 (dout, (uint16_t) pixel);
   350                          ++dout;
   351                      }
   352                      nDec += nBytes;
   353                      break;
   354                  }
   355                  case EXR_PIXEL_FLOAT: {
   356                      const uint8_t* ptr[3];
   357                      uint32_t       pixel = 0;
   358                      uint32_t*      dout  = (uint32_t*) (out);
   359
   360                      ptr[0] = lastIn;
   361                      lastIn += w;
   362                      ptr[1] = lastIn;
   363                      lastIn += w;
   364                      ptr[2] = lastIn;
   365                      lastIn += w;
   366
   367                      if (nDec + (uint64_t) (w * 3) > outSize)
   368                          return EXR_ERR_CORRUPT_CHUNK;
   369
   370                      for (int x = 0; x < w; ++x)
   371                      {
   372                          uint32_t diff =
   373                              (((uint32_t) (*(ptr[0]++)) << 24) |
   374                               ((uint32_t) (*(ptr[1]++)) << 16) |
   375                               ((uint32_t) (*(ptr[2]++)) << 8));
   376                          pixel += diff;
   377                          unaligned_store32 (dout, pixel);
   378                          ++dout;
   379                      }
   380                      nDec += (uint64_t) (w * 3);
   381                      break;
   382                  }
   383                  default: return EXR_ERR_INVALID_ARGUMENT;
   384              }
   385              out += nBytes;
   386              nOut += nBytes;
   387          }
   388      }
   389      return EXR_ERR_SUCCESS;
   390  }
   391
   392  exr_result_t
   393  internal_exr_undo_pxr24 (
   394      exr_decode_pipeline_t* decode,
   395      const void*            compressed_data,
   396      uint64_t               comp_buf_size,
   397      void*                  uncompressed_data,
   398      uint64_t               uncompressed_size)
   399  {
   400      exr_result_t rv;
   401      rv = internal_decode_alloc_buffer (
   402          decode,
   403          EXR_TRANSCODE_BUFFER_SCRATCH1,
   404          &(decode->scratch_buffer_1),
   405          &(decode->scratch_alloc_size_1),
   406          uncompressed_size);
   407      if (rv != EXR_ERR_SUCCESS) return rv;
   408      return undo_pxr24_impl (
   409          decode,
   410          compressed_data,
   411          comp_buf_size,
   412          uncompressed_data,
   413          uncompressed_size,
   414          decode->scratch_buffer_1,
   415          decode->scratch_alloc_size_1);
   416  }

698  exr_result_t
   699  exr_read_scanline_chunk_info (
   700      exr_const_context_t ctxt, int part_index, int y, exr_chunk_info_t* cinfo)
   701  {
   702      exr_result_t     rv;
   703      int              miny, cidx, rdcnt, lpc;
   704      int32_t          data[3];
   705      int64_t          ddata[3];
   706      int64_t          fsize;
   707      uint64_t         chunkmin, dataoff;
   708      exr_attr_box2i_t dw;
   709      uint64_t*        ctable;
   710      EXR_PROMOTE_READ_CONST_CONTEXT_AND_PART_OR_ERROR (ctxt, part_index);
   711
   712      if (!cinfo) return pctxt->standard_error (pctxt, EXR_ERR_INVALID_ARGUMENT);
   713
   714      if (part->storage_mode == EXR_STORAGE_TILED ||
   715          part->storage_mode == EXR_STORAGE_DEEP_TILED)
   716      {
   717          return pctxt->standard_error (pctxt, EXR_ERR_SCAN_TILE_MIXEDAPI);
   718      }
   719
   720      dw = part->data_window;
   721      if (y < dw.min.y || y > dw.max.y)
   722      {
   723          return pctxt->print_error (
   724              pctxt,
   725              EXR_ERR_INVALID_ARGUMENT,
   726              "Invalid request for scanline %d outside range of data window (%d - %d)",
   727              y,
   728              dw.min.y,
   729              dw.max.y);
   730      }
   731
   732      lpc  = part->lines_per_chunk;
   733      cidx = (y - dw.min.y);
   734      if (lpc > 1) cidx /= lpc;
   735
   736      // do we need to invert this when reading decreasing y? it appears not
   737      //if (part->lineorder == EXR_LINEORDER_DECREASING_Y)
   738      //    cidx = part->chunk_count - (cidx + 1);
   739      miny = (dw.min.y + cidx * lpc);
   740
   741      if (cidx < 0 || cidx >= part->chunk_count)
   742      {
   743          return pctxt->print_error (
   744              pctxt,
   745              EXR_ERR_INVALID_ARGUMENT,
   746              "Invalid request for scanline %d in chunk %d outside chunk count %d",
   747              y,
   748              cidx,
   749              part->chunk_count);
   750      }
   751
   752      cinfo->idx         = cidx;
   753      cinfo->type        = (uint8_t) part->storage_mode;
   754      cinfo->compression = (uint8_t) part->comp_type;
   755      cinfo->start_x     = dw.min.x;
   756      cinfo->start_y     = miny;
   757      cinfo->width       = dw.max.x - dw.min.x + 1;
   758      cinfo->height      = lpc;
   759      if (miny < dw.min.y)
   760      {
   761          cinfo->start_y = dw.min.y;
   762          cinfo->height -= (dw.min.y - miny);
   763      }
   764      else if ((miny + lpc) > dw.max.y)
   765      {
   766          cinfo->height = (dw.max.y - miny + 1);
   767      }
   768      cinfo->level_x = 0;
   769      cinfo->level_y = 0;
   770
   771      /* need to read from the file to get the packed chunk size */
   772      rv = extract_chunk_table (pctxt, part, &ctable, &chunkmin);
   773      if (rv != EXR_ERR_SUCCESS) return rv;
   774
   775      fsize = pctxt->file_size;
   776
   777      dataoff = ctable[cidx];
   778      if (dataoff < chunkmin || (fsize > 0 && dataoff > (uint64_t) fsize))
   779      {
   780          return pctxt->print_error (
   781              pctxt,
   782              EXR_ERR_BAD_CHUNK_LEADER,
   783              "Corrupt chunk offset table: scanline %d, chunk index %d recorded at file offset %" PRIu64,
   784              y,
   785              cidx,
   786              dataoff);
   787      }
   788
   789      /* TODO: Look at collapsing this into extract_chunk_leader, only
   790       * issue is more concrete error messages */
   791      /* multi part files have the part for validation */
   792      rdcnt = (pctxt->is_multipart) ? 2 : 1;
   793      /* deep has 64-bit data, so be variable about what we read */
   794      if (part->storage_mode != EXR_STORAGE_DEEP_SCANLINE) ++rdcnt;
   795
   796      rv = pctxt->do_read (
   797          pctxt,
   798          data,
   799          (size_t) (rdcnt) * sizeof (int32_t),
   800          &dataoff,
   801          NULL,
   802          EXR_MUST_READ_ALL);
   803
   804      if (rv != EXR_ERR_SUCCESS) return rv;
   805
   806      priv_to_native32 (data, rdcnt);
   807
   808      rdcnt = 0;
   809      if (pctxt->is_multipart)
   810      {
   811          if (data[rdcnt] != part_index)
   812          {
   813              return pctxt->print_error (
   814                  pctxt,
   815                  EXR_ERR_BAD_CHUNK_LEADER,
   816                  "Preparing read scanline %d (chunk %d), found corrupt leader: part says %d, expected %d",
   817                  y,
   818                  cidx,
   819                  data[rdcnt],
   820                  part_index);
   821          }
   822          ++rdcnt;
   823      }
   824      if (miny != data[rdcnt])
   825      {
   826          return pctxt->print_error (
   827              pctxt,
   828              EXR_ERR_BAD_CHUNK_LEADER,
   829              "Preparing to read scanline %d (chunk %d), found corrupt leader: scanline says %d, expected %d",
   830              y,
   831              cidx,
   832              data[rdcnt],
   833              miny);
   834      }
   835
   836      if (part->storage_mode == EXR_STORAGE_DEEP_SCANLINE)
